function example() {
  const [search, setSearch] = useState('kraken');
  const searchRef = React.useRef<HTMLInputElement>(null);
  const projects = [
    { id: 'p1', name: 'Apollo' },
    { id: 'p2', name: 'Gemini' },
    { id: 'p3', name: 'Mercury' },
  ];

  return (
    <DataTable
      caption="Projects"
      columns={[{ id: 'name', header: 'Project', isRowHeader: true }]}
      data={projects}
      search={search}
      onSearchChange={setSearch}
      isFullwidth
      toolbar={table => (
        <Input
          ref={searchRef}
          label="Search projects"
          {...table.getSearchProps()}
        />
      )}
      noResults={
        <EmptyState
          size="small"
          title={`No projects match “${search}”`}
          titleAs="h3"
          description="Check the spelling, or clear the search."
        >
          <Button
            size="small"
            onClick={() => {
              setSearch('');
              searchRef.current?.focus();
            }}
          >
            Clear search
          </Button>
        </EmptyState>
      }
    />
  );
}

import type { DataTableSort } from '@allxsmith/bestax-bulma';

function example() {
  const everyone = Array.from({ length: 23 }, (_, i) => ({
    id: `u${i + 1}`,
    name: `User ${i + 1}`,
    visits: (i * 37) % 100,
  }));
  const pageSize = 5;
  const [page, setPage] = useState(1);
  const [sort, setSort] = useState<DataTableSort[]>([]);
  const [search, setSearch] = useState('');
  const [result, setResult] = useState({
    rows: everyone.slice(0, 0),
    total: 0,
  });
  const [loading, setLoading] = useState(true);
  // Each change starts a fetch, so the table shows it's loading.
  const fetching =
    <T,>(set: (value: T) => void) =>
    (value: T) => {
      setLoading(true);
      set(value);
    };

  useEffect(() => {
    const timer = setTimeout(() => {
      // What the server does with the query.
      const matched = everyone.filter(row =>
        row.name.toLowerCase().includes(search.trim().toLowerCase())
      );
      const [by] = sort;
      if (by?.id === 'visits') {
        matched.sort((a, b) =>
          by.direction === 'ascending'
            ? a.visits - b.visits
            : b.visits - a.visits
        );
      }
      setResult({
        rows: matched.slice((page - 1) * pageSize, page * pageSize),
        total: matched.length,
      });
      setLoading(false);
    }, 500);
    return () => clearTimeout(timer);
  }, [page, sort, search]);

  return (
    <DataTable
      caption="Visitors"
      columns={[
        { id: 'name', header: 'Name', isRowHeader: true },
        { id: 'visits', header: 'Visits', sortable: true, align: 'right' },
      ]}
      data={result.rows}
      manual
      rowCount={result.total}
      loading={loading}
      pageSize={pageSize}
      page={page}
      onPageChange={fetching(setPage)}
      sort={sort}
      onSortChange={fetching(setSort)}
      hasSearch
      search={search}
      onSearchChange={fetching(setSearch)}
      isFullwidth
    />
  );
}

